import Auth from '/global/auth/auth-state.js';
const key='leakendia.guest-cart.v1',endpoint='/api/marketplace/cart';
function guest(){try{const a=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(a)?a.filter(x=>x&&typeof x.offer_id==='string'&&Number.isInteger(x.quantity)&&x.quantity>0&&x.quantity<=20).slice(0,50):[];}catch{return [];}}
function save(a){localStorage.setItem(key,JSON.stringify(a));}
async function api(body){const r=await fetch(endpoint,{credentials:'same-origin',cache:'no-store',...(body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{})});const j=await r.json();if(!r.ok||!j.success)throw Error(j.error||'Cart unavailable');return j.items;}
async function state(){await Auth.init();const s=Auth.getState();if(s.error)throw Error('Unable to verify sign-in');return s.authenticated;}
async function sync(){const pending=guest();if(pending.length){const rows=await api({mode:'merge',items:pending.map(({offer_id,quantity})=>({offer_id,quantity}))});save([]);return rows;}return api();}
export async function addOffer(service,offer,go=false){if(await state()){await sync();await api({mode:'merge',items:[{offer_id:offer.id,quantity:1}]});}else{const rows=guest();if(!rows.some(x=>x.offer_id===offer.id)){if(rows.length>=50)throw Error('Cart is full');rows.push({offer_id:offer.id,quantity:1,title:service.title,name:offer.name});save(rows);}}if(go)location.assign('/marketplace/cart');}
const root=document.getElementById('cart-items');
if(root){const status=document.getElementById('cart-status'),next=document.getElementById('cart-next');let busy=false;async function render(){const signed=await state();const rows=signed?await sync():guest();root.replaceChildren();status.textContent=rows.length?'':'Your cart is empty.';next.textContent=signed?'Submit service request':'Sign in to save cart';next.disabled=signed&&(!rows.length||rows.some(x=>!x.available));next.onclick=async()=>{if(!signed){location.assign(Auth.getSignInURL('/marketplace/cart'));return;}if(busy)return;busy=true;next.disabled=true;try{const storageKey='leakendia.request-key.'+Auth.getState().customer.id;let submissionKey=sessionStorage.getItem(storageKey);if(!submissionKey){submissionKey=crypto.randomUUID();sessionStorage.setItem(storageKey,submissionKey);}const r=await fetch('/api/marketplace/requests',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({submissionKey,requirements:document.getElementById('request-requirements').value})});const j=await r.json();if(!r.ok||!j.success)throw Error(j.error||'Submission failed');sessionStorage.removeItem(storageKey);location.assign('/pages/portal/portal.html#requests');}catch(e){status.textContent=e.message;next.disabled=false;}finally{busy=false;}};for(const row of rows){const box=document.createElement('div');box.className='cart-row';const title=document.createElement('strong');title.textContent=(row.title||'Service')+' / '+(row.name||'Offer');const price=document.createElement('span');price.textContent=!signed?'Price verified after sign-in':row.available===0?'Unavailable':row.price_minor==null?'Custom quote':row.currency+' '+(row.price_minor/100).toFixed(2)+(row.model==='weekly'?' / week':'');const qty=document.createElement('input');qty.type='number';qty.min=1;qty.max=20;qty.value=row.quantity;qty.setAttribute('aria-label','Quantity');const remove=document.createElement('button');remove.textContent='Remove';async function change(n){if(busy)return;busy=true;try{if(signed)await api({mode:'set',items:[{offer_id:row.offer_id,quantity:n}]});else save(guest().flatMap(x=>x.offer_id!==row.offer_id?[x]:n?[{...x,quantity:n}]:[]));await render();}catch(e){status.textContent=e.message;qty.value=row.quantity;}finally{busy=false;}}qty.onchange=()=>{const n=Number(qty.value);if(Number.isInteger(n)&&n>=1&&n<=20)change(n);else qty.value=row.quantity;};remove.onclick=()=>change(0);box.append(title,price,qty,remove);root.append(box);}}render().catch(e=>status.textContent=e.message);}
